from z3 import *
import time

n_golfers = 50
n_groups = 10
n_weeks = 7

# group[w][p] = group of golfer p in week w
group = [[Int(f"g_{w}_{p}") for p in range(n_golfers)] for w in range(n_weeks)]

s = Solver()
s.set("timeout", 55000)  # 55 seconds

# Domain
for w in range(n_weeks):
    for p in range(n_golfers):
        s.add(group[w][p] >= 0, group[w][p] < n_groups)

# Week 0: fixed
for p in range(n_golfers):
    s.add(group[0][p] == p // 5)

# Group size constraints for weeks 1..6
for w in range(1, n_weeks):
    for g in range(n_groups):
        s.add(Sum([If(group[w][p] == g, 1, 0) for p in range(n_golfers)]) == 5)

# No pair meets twice
for i in range(n_golfers):
    for j in range(i+1, n_golfers):
        if i // 5 == j // 5:
            # Same group in week 0, can never meet again
            for w in range(1, n_weeks):
                s.add(group[w][i] != group[w][j])
        else:
            # Different groups in week 0, can meet at most once
            s.add(Sum([If(group[w][i] == group[w][j], 1, 0) for w in range(1, n_weeks)]) <= 1)

print("Solving...")
start = time.time()
result = s.check()
print(f"Result: {result}, time: {time.time() - start:.2f}s")

if result == sat:
    model = s.model()
    schedule = []
    for w in range(n_weeks):
        for p in range(n_golfers):
            schedule.append(model.evaluate(group[w][p]).as_long())
    print("Schedule found, length:", len(schedule))
    # Verify
    ok = True
    for i in range(n_golfers):
        for j in range(i+1, n_golfers):
            count = 0
            for w in range(n_weeks):
                if schedule[w*50 + i] == schedule[w*50 + j]:
                    count += 1
            if count > 1:
                print(f"ERROR: pair ({i},{j}) meets {count} times")
                ok = False
    if ok:
        print("Verification passed!")
        print("First 50 values (week 0):", schedule[:50])
        print("Next 50 values (week 1):", schedule[50:100])
elif result == unsat:
    print("UNSATISFIABLE")
else:
    print("UNKNOWN (timeout or other)")

import random

def build_week(pairs_met, n_golfers=50, n_groups=10, group_size=5):
    available = set(range(n_golfers))
    groups = []

    for g in range(n_groups):
        group = []
        if not available:
            return None
        first = min(available)
        group.append(first)
        available.remove(first)

        for _ in range(group_size - 1):
            candidates = []
            for p in available:
                ok = True
                for q in group:
                    if frozenset({p, q}) in pairs_met:
                        ok = False
                        break
                if ok:
                    candidates.append(p)
            if not candidates:
                return None
            best = min(candidates, key=lambda p: sum(1 for q in available if q != p and frozenset({p, q}) not in pairs_met))
            group.append(best)
            available.remove(best)

        groups.append(group)

    return groups

