import time

n_golfers = 50
n_groups = 10
n_weeks = 7

# x[w][p][g] = golfer p is in group g in week w
x = [[[Bool("x_%d_%d_%d" % (w, p, g)) for g in range(n_groups)] for p in range(n_golfers)] for w in range(n_weeks)]

s = Solver()
s.set("timeout", 50000)

# Each golfer in exactly one group per week
for w in range(n_weeks):
    for p in range(n_golfers):
        # Exactly one group
        s.add(Sum([If(x[w][p][g], 1, 0) for g in range(n_groups)]) == 1)

# Each group has exactly 5 golfers per week
for w in range(n_weeks):
    for g in range(n_groups):
        s.add(Sum([If(x[w][p][g], 1, 0) for p in range(n_golfers)]) == 5)

# Week 0: fixed
for p in range(n_golfers):
    g0 = p // 5
    s.add(x[0][p][g0])
    for g in range(n_groups):
        if g != g0:
            s.add(Not(x[0][p][g]))

# No pair meets twice
for i in range(n_golfers):
    for j in range(i+1, n_golfers):
        # Count weeks where i and j are in same group
        same_group = [Or([And(x[w][i][g], x[w][j][g]) for g in range(n_groups)]) for w in range(n_weeks)]
        s.add(Sum([If(same_group[w], 1, 0) for w in range(n_weeks)]) <= 1)

print("Solving with boolean encoding...")
start = time.time()
result = s.check()
print("Result: %s, time: %.2fs" % (result, time.time() - start))

if result == sat:
    model = s.model()
    schedule = []
    for w in range(n_weeks):
        for p in range(n_golfers):
            for g in range(n_groups):
