                if schedule[w*50 + i] == schedule[w*50 + j]:
                    count += 1
            if count > 1:
                print("ERROR: pair (%d,%d) meets %d times" % (i, j, count))
                ok = False
    if ok:
        print("Verification passed!")
elif result == unsat:
    print("UNSATISFIABLE")
else:
